import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"30、【离】 离下离上","description":"周易阐真 - 30、【离】 离下离上","frontmatter":{"title":"30、【离】 离下离上","description":"周易阐真 - 30、【离】 离下离上"},"headers":[],"relativePath":"zh/classics/chanzhen/031.md","filePath":"zh/classics/chanzhen/031.md"}'),s={name:"zh/classics/chanzhen/031.md"};function n(c,p,i,o,h,l){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：离，丽也。日月丽乎天，百谷草木丽乎土。重明以丽乎正，乃化成天下。柔丽乎中正，故亨，是以畜牝牛吉也。</p></blockquote><h1 id="_30、【离】-离下离上" tabindex="-1">30、【离】 离下离上 <a class="header-anchor" href="#_30、【离】-离下离上" aria-label="Permalink to “30、【离】 离下离上”">​</a></h1><p>初九：履错然，敬之，无咎。</p><p>六二：黄离，元吉。</p><p>九三：日昃之离，不鼓缶而歌，则大耋之嗟，凶。</p><p>九四：突如其来如，焚如，死如，弃如。</p><p>六五：出涕沱若，戚嗟若，吉。</p><p>上九：王用出征，有嘉，折首，获匪其丑，无咎。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：明两作，离。大人以继明照于四方。</p><p>离者，日明之谓。上离日，下离日，日之运用，夜则入地而内明，昼则出地而外明，一明而有两作，此离之象也。</p><p>大人有见于此，知人不能明内，则必不能明外，先明内，后明外，明内如是，明外亦如是。以是明内已毕，又继其明而照于四方也。明者，明内也；继明者，又明外也。明者何明，即明其本来一点虚灵不昧之德耳。能虚能灵，内德已明，诚于中而达于外，无物能瞒，无事有累，照于四方，如在掌上，大地里黄芽长遍，满世界金花开绽，左之右之，头头是道，内外通彻，其明不息，方且自明明德而止于至善矣。但继明照四方，非是空空无为即便了事，其中有增减之功。曰明照者，以明而照也。明不能照于四方，其明不大，不为继明。既明内，又明外，明而必如日升虚空，下照万物，万物莫能蔽其明，方是真明，方是继明。若稍有些子照不到，即有些子蔽其明。明能照于四方，纵横逆顺，皆不碍其照，无处不通，无处有伤，明明德之功尽矣。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>畜，昌六反。昃，音仄。耋，音咥。突，同忽反。</p><p>离者，丽也，明也。卦体一阴附丽于二阳之中，虚中能明之象。卦德上离明，下离明，由此明而及彼明，由彼明而达此明，明内而又明外，内明而又外明。千明万明，总是两明，内明外明，总是一明，故谓离。此雄里怀雌、阳中有阴之卦，承上大过而来。</p><p>大过者，阳刚太过，雄而不雌，任心造化，误用其明矣。明者，离宫虚灵之气，为人之神，心之主。心虚则灵，元神主事，明而得正，能以济阳。心乱则迷，识神主事，明而不当，足以伤阳，是以离利于贞而亨也。然虽离利于贞而亨，若只知用明，不知养明，亦不得亨。</p><p>夫用明者，外明也；养明者，内明也。外明必本于内明，用明须当先养明，是以又畜牝牛吉也。</p><p>畜者，养也。牛者，顺象。牛至于牝，绝不用刚，其性至顺，人能以柔顺养明，雌而不雄，回光反照，闲邪存诚，先明内而后明外，内外俱明，虚灵不昧，无一物能瞒，无一物能移。自明明德而止于至善，其吉为何如乎！</p><p>但明而致吉之道，有火候，有工程，稍有不谨，明而不亨，故明必至于内外，无一不明，无一不正，方是明之利、明之亨、明之吉也。</p><p>初九，在明之初，不知养明，而即用明，履必错然也。错然之履，不但不能进明，而且有以伤明，惟敬之、博学之、审问之、慎思之、明辨之，自始自终，了然于心，而后笃行之，方无错然之咎矣。此用明须当先求明者也。</p><p>六二，自知不明，而能虚心下贤求人之明，是谓黄离也。黄为中色，明而归中，示己之无，尊人之有，虽愚必明，虽柔必强，不失其柔顺之本质，其吉在于能虚心矣。此不明而求人之明者也。</p><p>九三，独刚不柔，只知用明，不知养明，刚明太过，如日昃过缶之明，高极必下，明极必暗，是不能鼓缶而歌，则有大耋之嗟，不中不和，适以取凶而已。此用明而自败其明者也。</p><p>九四，刚而不正，不能明内，即欲明外，是突如其来如也。突来之明，躐等而求，性躁行偏，妄作招凶，焚如，死如，弃如，欲求长生，反而伤命。此不明而自以为明者也。</p><p>六五，居外明之中，所当明内而又明外者，乃懦弱无能，或见理不真，或力有不及，是以出涕沱若，戚嗟若也。然涕沱戚嗟，不敢妄作妄为，自守本分，亦致吉之道。此明而知己不明者也。</p><p>上九，居重明之上，刚而有为，既能明内，又能明外，既能明顺，又能明逆，取象王用出征，有嘉折首，获匪其丑也。</p><p>人之真心，如王明明德，如出征，明德而德即明，如有嘉功，除去人心，如折首恶，不强制杂念，如不获从丑，用明而至折首之明，则后天一切客气，不退而自化，寂然不动，感而遂通，内外光明，而无一毫根尘之咎矣。此明而至善无恶者也。</p><p>然则用明之道，须要知雄守雌，刚中有柔，明而得正为贵乎。倘有刚无柔，不落于突如其来，即归于日昃之离，不但不能增明，而反有以伤明。修道者，欲用其明，可不先养其明乎！</p>',27)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
